import{_ as l,a0 as t,w as o,s as d,ao as c,I as p,x as a,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"8 個用於有效地管理進程的 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"8 個用於有效地管理進程的 Linux 命令 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"8 個用於有效地管理進程的 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"8 個用於有效地管理進程的 Linux 命令 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180904 8 Linux commands for effective process management","title":"8 個用於有效地管理進程的 Linux 命令","tag":"201809","desc":""},"relativePath":"201809/20180904 8 Linux commands for effective process management.md","filePath":"[post].md"}'),r={name:"201809/20180904 8 Linux commands for effective process management.md"};function h(g,s,k,b,u,f){const n=t("Link");return o(),d("div",null,[s[18]||(s[18]=c(`<h1 id="_8-個用於有效地管理進程的-linux-命令" tabindex="-1">8 個用於有效地管理進程的 Linux 命令 <a class="header-anchor" href="#_8-個用於有效地管理進程的-linux-命令" aria-label="Permalink to “8 個用於有效地管理進程的 Linux 命令”">​</a></h1><blockquote><p>通過這些關鍵的命令來全程管理你的應用。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/command_line_prompt.png?itok=wbGiJ_yg" alt=""></p><p>一般來説，應用程序進程的生命週期有三種主要狀態：啓動、運行和停止。如果我們想成為稱職的管理員，每個狀態都可以而且應該得到認真的管理。這八個命令可用於管理進程的整個生命週期。</p><h3 id="啓動進程" tabindex="-1">啓動進程 <a class="header-anchor" href="#啓動進程" aria-label="Permalink to “啓動進程”">​</a></h3><p>啓動進程的最簡單方法是在命令列中鍵入其名稱，然後按回車鍵。如果要啓動 Nginx web 服務器，請鍵入 <code>nginx</code> 。也許您只是想看看其版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ nginx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation:~$ nginx -v</span></span>
<span class="line"><span>nginx version: nginx/1.14.0</span></span></code></pre></div><h3 id="查看您的可執行路徑" tabindex="-1">查看您的可執行路徑 <a class="header-anchor" href="#查看您的可執行路徑" aria-label="Permalink to “查看您的可執行路徑”">​</a></h3><p>以上啓動進程的演示是假設可執行文件位於您的可執行路徑中。理解這個路徑是可靠地啓動和管理進程的關鍵。管理員通常會為他們想要的目的定製這條路徑。您可以使用 <code>echo $PATH</code> 查看您的可執行路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ echo $PATH</span></span>
<span class="line"><span>/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin</span></span></code></pre></div><h4 id="which" tabindex="-1">WHICH <a class="header-anchor" href="#which" aria-label="Permalink to “WHICH”">​</a></h4><p>使用 <code>which</code> 命令查看可執行文件的完整路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ which nginx</span></span>
<span class="line"><span>/opt/nginx/bin/nginx</span></span></code></pre></div><p>我將使用流行的 web 服務器軟件 Nginx 作為我的例子。假設安裝了 Nginx。如果執行 <code>which nginx</code> 的命令什麼也不返回，那麼是找不到 Nginx 了，因為它只搜索您指定的可執行路徑。有三種方法可以補救一個進程不能簡單地通過名字啓動的情況。首先是鍵入完整路徑 —— 雖然，我不情願輸入全部路徑，您會嗎？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ /home/alan/web/prod/nginx/sbin/nginx -v</span></span>
<span class="line"><span>nginx version: nginx/1.14.0</span></span></code></pre></div><p>第二個解決方案是將應用程序安裝在可執行文件路徑中的目錄中。然而，這有時可能是辦不到的，特別是如果您沒有 root 權限。</p><p>第三個解決方案是更新您的可執行路徑環境變量，包括要使用的特定應用程序的安裝目錄。這個解決方案是與 shell 相關的。例如，Bash 用户需要在他們的 <code>.bashrc</code> 文件中編輯 <code>PATH=</code> 行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATH=&quot;$HOME/web/prod/nginx/sbin:$PATH&quot;</span></span></code></pre></div><p>現在，重複您的 <code>echo</code> 和 <code>which</code> 命令或者嘗試檢查版本。容易多了！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ echo $PATH</span></span>
<span class="line"><span>/home/alan/web/prod/nginx/sbin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation:~$ which nginx</span></span>
<span class="line"><span>/home/alan/web/prod/nginx/sbin/nginx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation:~$ nginx -v                                                </span></span>
<span class="line"><span>nginx version: nginx/1.14.0</span></span></code></pre></div><h3 id="保持進程運行" tabindex="-1">保持進程運行 <a class="header-anchor" href="#保持進程運行" aria-label="Permalink to “保持進程運行”">​</a></h3><h4 id="nohup" tabindex="-1">NOHUP <a class="header-anchor" href="#nohup" aria-label="Permalink to “NOHUP”">​</a></h4><p>註銷或關閉終端時，進程可能不會繼續運行。這種特殊情況可以通過在要使用 <code>nohup</code> 命令放在要運行的命令前面讓進程持續運行。此外，附加一個<code>&amp;</code> 符號將會把進程發送到後台，並允許您繼續使用終端。例如，假設您想運行 <code>myprogram.sh</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nohup myprogram.sh &amp;</span></span></code></pre></div><p><code>nohup</code> 會返回運行進程的 PID。接下來我會更多地談論 PID。</p><h3 id="管理正在運行的進程" tabindex="-1">管理正在運行的進程 <a class="header-anchor" href="#管理正在運行的進程" aria-label="Permalink to “管理正在運行的進程”">​</a></h3><p>每個進程都有一個唯一的進程標識號 (PID) 。這個數字是我們用來管理每個進程的。我們還可以使用進程名稱，我將在下面演示。有幾個命令可以檢查正在運行的進程的狀態。讓我們快速看看這些命令。</p><h4 id="ps" tabindex="-1">PS <a class="header-anchor" href="#ps" aria-label="Permalink to “PS”">​</a></h4><p>最常見的是 <code>ps</code> 命令。<code>ps</code> 的默認輸出是當前終端中運行的進程的簡單列表。如下所示，第一列包含 PID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ ps</span></span>
<span class="line"><span>PID TTY          TIME CMD</span></span>
<span class="line"><span>23989 pts/0    00:00:00 bash</span></span>
<span class="line"><span>24148 pts/0    00:00:00 ps</span></span></code></pre></div><p>我想看看我之前啓動的 Nginx 進程。為此，我告訴 <code>ps</code> 給我展示每一個正在運行的進程（<code>-e</code>）和完整的列表（<code>-f</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ ps -ef</span></span>
<span class="line"><span>UID        PID  PPID  C STIME TTY          TIME CMD</span></span>
<span class="line"><span>root         1     0  0 Aug18 ?        00:00:10 /sbin/init splash</span></span>
<span class="line"><span>root         2     0  0 Aug18 ?        00:00:00 [kthreadd]</span></span>
<span class="line"><span>root         4     2  0 Aug18 ?        00:00:00 [kworker/0:0H]</span></span>
<span class="line"><span>root         6     2  0 Aug18 ?        00:00:00 [mm_percpu_wq]</span></span>
<span class="line"><span>root         7     2  0 Aug18 ?        00:00:00 [ksoftirqd/0]</span></span>
<span class="line"><span>root         8     2  0 Aug18 ?        00:00:20 [rcu_sched]</span></span>
<span class="line"><span>root         9     2  0 Aug18 ?        00:00:00 [rcu_bh]</span></span>
<span class="line"><span>root        10     2  0 Aug18 ?        00:00:00 [migration/0]</span></span>
<span class="line"><span>root        11     2  0 Aug18 ?        00:00:00 [watchdog/0]</span></span>
<span class="line"><span>root        12     2  0 Aug18 ?        00:00:00 [cpuhp/0]</span></span>
<span class="line"><span>root        13     2  0 Aug18 ?        00:00:00 [cpuhp/1]</span></span>
<span class="line"><span>root        14     2  0 Aug18 ?        00:00:00 [watchdog/1]</span></span>
<span class="line"><span>root        15     2  0 Aug18 ?        00:00:00 [migration/1]</span></span>
<span class="line"><span>root        16     2  0 Aug18 ?        00:00:00 [ksoftirqd/1]</span></span>
<span class="line"><span>alan     20506 20496  0 10:39 pts/0    00:00:00 bash</span></span>
<span class="line"><span>alan     20520  1454  0 10:39 ?        00:00:00 nginx: master process nginx</span></span>
<span class="line"><span>alan     20521 20520  0 10:39 ?        00:00:00 nginx: worker process</span></span>
<span class="line"><span>alan     20526 20506  0 10:39 pts/0    00:00:00 man ps</span></span>
<span class="line"><span>alan     20536 20526  0 10:39 pts/0    00:00:00 pager</span></span>
<span class="line"><span>alan     20564 20496  0 10:40 pts/1    00:00:00 bash</span></span></code></pre></div><p>您可以在上面 <code>ps</code> 命令的輸出中看到 Nginx 進程。這個命令顯示了將近 300 行，但是我在這個例子中縮短了它。可以想像，試圖處理 300 行過程信息有點混亂。我們可以將這個輸出輸送到 <code>grep</code>，過濾一下僅顯示 nginx。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ ps -ef |grep nginx</span></span>
<span class="line"><span>alan     20520  1454  0 10:39 ?        00:00:00 nginx: master process nginx</span></span>
<span class="line"><span>alan     20521 20520  0 10:39 ?        00:00:00 nginx: worker process</span></span></code></pre></div><p>確實更好了。我們可以很快看到，Nginx 有 20520 和 20521 的 PID。</p><h4 id="pgrep" tabindex="-1">PGREP <a class="header-anchor" href="#pgrep" aria-label="Permalink to “PGREP”">​</a></h4><p><code>pgrep</code> 命令更加簡化單獨調用 <code>grep</code> 遇到的問題。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep nginx</span></span>
<span class="line"><span>20520</span></span>
<span class="line"><span>20521</span></span></code></pre></div><p>假設您在一個託管環境中，多個用户正在運行幾個不同的 Nginx 實例。您可以使用 <code>-u</code> 選項將其他人排除在輸出之外。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep -u alan nginx</span></span>
<span class="line"><span>20520</span></span>
<span class="line"><span>20521</span></span></code></pre></div><h4 id="pidof" tabindex="-1">PIDOF <a class="header-anchor" href="#pidof" aria-label="Permalink to “PIDOF”">​</a></h4><p>另一個好用的是 <code>pidof</code>。此命令將檢查特定二進制文件的 PID，即使另一個同名進程正在運行。為了建立一個例子，我將我的 Nginx 複製到第二個目錄，並以相應的路徑前綴啓動。在現實生活中，這個實例可能位於不同的位置，例如由不同用户擁有的目錄。如果我運行兩個 Nginx 實例，則<code>pidof</code> 輸出顯示它們的所有進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ ps -ef |grep nginx</span></span>
<span class="line"><span>alan     20881  1454  0 11:18 ?        00:00:00 nginx: master process ./nginx -p /home/alan/web/prod/nginxsec</span></span>
<span class="line"><span>alan     20882 20881  0 11:18 ?        00:00:00 nginx: worker process</span></span>
<span class="line"><span>alan     20895  1454  0 11:19 ?        00:00:00 nginx: master process nginx</span></span>
<span class="line"><span>alan     20896 20895  0 11:19 ?        00:00:00 nginx: worker process</span></span></code></pre></div><p>使用 <code>grep</code> 或 <code>pgrep</code> 將顯示 PID 數字，但我們可能無法辨別哪個實例是哪個。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep nginx</span></span>
<span class="line"><span>20881</span></span>
<span class="line"><span>20882</span></span>
<span class="line"><span>20895</span></span>
<span class="line"><span>20896</span></span></code></pre></div><p><code>pidof</code> 命令可用於確定每個特定 Nginx 實例的 PID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pidof /home/alan/web/prod/nginxsec/sbin/nginx</span></span>
<span class="line"><span>20882 20881</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation:~$ pidof /home/alan/web/prod/nginx/sbin/nginx</span></span>
<span class="line"><span>20896 20895</span></span></code></pre></div><h4 id="top" tabindex="-1">TOP <a class="header-anchor" href="#top" aria-label="Permalink to “TOP”">​</a></h4><p><code>top</code> 命令已經有很久的歷史了，對於查看運行進程的細節和快速識別內存消耗等問題是非常有用的。其默認視圖如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>top - 11:56:28 up 1 day, 13:37,  1 user,  load average: 0.09, 0.04, 0.03</span></span>
<span class="line"><span>Tasks: 292 total,   3 running, 225 sleeping,   0 stopped,   0 zombie</span></span>
<span class="line"><span>%Cpu(s):  0.1 us,  0.2 sy,  0.0 ni, 99.7 id,  0.0 wa,  0.0 hi,  0.0 si,  0.0 st</span></span>
<span class="line"><span>KiB Mem : 16387132 total, 10854648 free,  1859036 used,  3673448 buff/cache</span></span>
<span class="line"><span>KiB Swap:        0 total,        0 free,        0 used. 14176540 avail Mem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  PID USER      PR  NI    VIRT    RES    SHR S  %CPU %MEM     TIME+ COMMAND</span></span>
<span class="line"><span>17270 alan      20   0 3930764 247288  98992 R   0.7  1.5   5:58.22 gnome-shell</span></span>
<span class="line"><span>20496 alan      20   0  816144  45416  29844 S   0.5  0.3   0:22.16 gnome-terminal-</span></span>
<span class="line"><span>21110 alan      20   0   41940   3988   3188 R   0.1  0.0   0:00.17 top</span></span>
<span class="line"><span>    1 root      20   0  225564   9416   6768 S   0.0  0.1   0:10.72 systemd</span></span>
<span class="line"><span>    2 root      20   0       0      0      0 S   0.0  0.0   0:00.01 kthreadd</span></span>
<span class="line"><span>    4 root       0 -20       0      0      0 I   0.0  0.0   0:00.00 kworker/0:0H</span></span>
<span class="line"><span>    6 root       0 -20       0      0      0 I   0.0  0.0   0:00.00 mm_percpu_wq</span></span>
<span class="line"><span>    7 root      20   0       0      0      0 S   0.0  0.0   0:00.08 ksoftirqd/0</span></span></code></pre></div><p>可以通過鍵入字母 <code>s</code> 和您喜歡的更新秒數來更改更新間隔。為了更容易監控我們的示例 Nginx 進程，我們可以使用 <code>-p</code> 選項並傳遞 PID 來調用 <code>top</code>。這個輸出要乾淨得多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ top -p20881 -p20882 -p20895 -p20896</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tasks:   4 total,   0 running,   4 sleeping,   0 stopped,   0 zombie</span></span>
<span class="line"><span>%Cpu(s):  2.8 us,  1.3 sy,  0.0 ni, 95.9 id,  0.0 wa,  0.0 hi,  0.0 si,  0.0 st</span></span>
<span class="line"><span>KiB Mem : 16387132 total, 10856008 free,  1857648 used,  3673476 buff/cache</span></span>
<span class="line"><span>KiB Swap:        0 total,        0 free,        0 used. 14177928 avail Mem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  PID USER      PR  NI    VIRT    RES    SHR S  %CPU %MEM     TIME+ COMMAND</span></span>
<span class="line"><span>20881 alan      20   0   12016    348      0 S   0.0  0.0   0:00.00 nginx</span></span>
<span class="line"><span>20882 alan      20   0   12460   1644    932 S   0.0  0.0   0:00.00 nginx</span></span>
<span class="line"><span>20895 alan      20   0   12016    352      0 S   0.0  0.0   0:00.00 nginx</span></span>
<span class="line"><span>20896 alan      20   0   12460   1628    912 S   0.0  0.0   0:00.00 nginx</span></span></code></pre></div><p>在管理進程，特別是終止進程時，正確確定 PID 是非常重要。此外，如果以這種方式使用 <code>top</code>，每當這些進程中的一個停止或一個新進程開始時，<code>top</code> 都需要被告知有新的進程。</p><h3 id="終止進程" tabindex="-1">終止進程 <a class="header-anchor" href="#終止進程" aria-label="Permalink to “終止進程”">​</a></h3><h4 id="kill" tabindex="-1">KILL <a class="header-anchor" href="#kill" aria-label="Permalink to “KILL”">​</a></h4><p>有趣的是，沒有 <code>stop</code> 命令。在 Linux 中，有 <code>kill</code> 命令。<code>kill</code> 用於向進程發送信號。最常用的信號是“終止”（<code>SIGTERM</code>）或“殺死”（<code>SIGKILL</code>）。然而，還有更多。下面是一些例子。完整的列表可以用 <code>kill -L</code> 顯示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 1) SIGHUP       2) SIGINT       3) SIGQUIT      4) SIGILL       5) SIGTRAP</span></span>
<span class="line"><span> 6) SIGABRT      7) SIGBUS       8) SIGFPE       9) SIGKILL     10) SIGUSR1</span></span>
<span class="line"><span>11) SIGSEGV     12) SIGUSR2     13) SIGPIPE     14) SIGALRM     15) SIGTERM</span></span></code></pre></div><p>注意第 9 號信號是 <code>SIGKILL</code>，通常，我們會發出比如 <code>kill -9 20896</code> 這樣的命令。默認信號是 15，這是 <code>SIGTERM</code>。請記住，許多應用程序都有自己的停止方法。Nginx 使用 <code>-s</code> 選項傳遞信號，如 <code>stop</code> 或 <code>reload</code>。通常，我更喜歡使用應用程序的特定方法來停止操作。然而，我將演示用 <code>kill</code> 命令來停止 Nginx 進程 20896，然後用 <code>pgrep</code> 確認它已經停止。PID 20896 就不再出現。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ kill -9 20896</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>alan@workstation:~$ pgrep nginx</span></span>
<span class="line"><span>20881</span></span>
<span class="line"><span>20882</span></span>
<span class="line"><span>20895</span></span>
<span class="line"><span>22123</span></span></code></pre></div><h4 id="pkill" tabindex="-1">PKILL <a class="header-anchor" href="#pkill" aria-label="Permalink to “PKILL”">​</a></h4><p>命令 <code>pkill</code> 類似於 <code>pgrep</code>，因為它可以按名稱搜索。這意味着在使用 <code>pkill</code> 時必須非常小心。在我的 Nginx 示例中，如果我只想殺死一個 Nginx 實例，我可能不會選擇使用它。我可以將 Nginx 選項 <code>-s stop</code> 傳遞給特定的實例來消除它，或者我需要使用 <code>grep</code> 來過濾整個 <code>ps</code> 輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home/alan/web/prod/nginx/sbin/nginx -s stop</span></span>
<span class="line"><span>/home/alan/web/prod/nginxsec/sbin/nginx -s stop</span></span></code></pre></div><p>如果我想使用 <code>pkill</code>，我可以包括 <code>-f</code> 選項，讓 <code>pkill</code> 過濾整個命令列參數。這當然也適用於 <code>pgrep</code>。所以，在執行 <code>pkill -f</code> 之前，首先我可以用 <code>pgrep -a</code> 確認一下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep -a nginx</span></span>
<span class="line"><span>20881 nginx: master process ./nginx -p /home/alan/web/prod/nginxsec</span></span>
<span class="line"><span>20882 nginx: worker process</span></span>
<span class="line"><span>20895 nginx: master process nginx</span></span>
<span class="line"><span>20896 nginx: worker process</span></span></code></pre></div><p>我也可以用 <code>pgrep -f</code> 縮小我的結果。<code>pkill</code> 使用相同參數會停止該進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep -f nginxsec</span></span>
<span class="line"><span>20881</span></span>
<span class="line"><span>                                           </span></span>
<span class="line"><span>alan@workstation:~$ pkill -f nginxsec</span></span></code></pre></div><p><code>pgrep</code>（尤其是 <code>pkill</code>）要記住的關鍵點是，您必須始終確保搜索結果準確性，這樣您就不會無意中影響到錯誤的進程。</p>`,67)),p("p",null,[s[1]||(s[1]=a("大多數這些命令都有許多命令列選項，所以我總是建議閲讀每一個命令的 ",-1)),i(n,{href:"https://www.kernel.org/doc/man-pages/"},{default:e(()=>[...s[0]||(s[0]=[a("man 手冊頁",-1)])]),_:1}),s[2]||(s[2]=a("。雖然大多數這些命令都存在於 Linux、Solaris 和 BSD 等平台上，但也有一些不同之處。在命令列工作或編寫腳本時，始終測試並隨時準備根據需要進行更正。",-1))]),s[19]||(s[19]=p("hr",null,null,-1)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/18/9/linux-commands-process-management"},{default:e(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/18/9/linux-commands-process-management",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/alanfdoss"},{default:e(()=>[...s[5]||(s[5]=[a("Alan Formy-Duval",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),i(n,{href:"https://github.com/heguangzhi"},{default:e(()=>[...s[7]||(s[7]=[a("heguangzhi",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const C=l(r,[["render",h]]);export{y as __pageData,C as default};
